import re
import math
import operator
from flask import Flask, request, jsonify

app = Flask(__name__)

# Supported operators
OPERATORS = {
    '+': operator.add,
    '-': operator.sub,
    '*': operator.mul,
    '/': operator.truediv,
    '^': operator.pow,
    '%': operator.mod,
}

# Precedence (higher number = higher precedence)
PRECEDENCE = {
    '+': 1,
    '-': 1,
    '*': 2,
    '/': 2,
    '^': 3,
    '%': 2,
}

def tokenize(expression):
    # Remove spaces
    expression = expression.replace(' ', '')
    # Regex to match numbers, operators, parentheses
    tokens = re.findall(r'\d+\.?\d*|[+\-*/^%()]', expression)
    if not tokens:
        raise ValueError("Empty expression")
    return tokens

def shunting_yard(tokens):
    output = []
    operators = []
    for token in tokens:
        if re.match(r'\d+\.?\d*', token):
            output.append(float(token))
        elif token in OPERATORS:
            while (operators and operators[-1] in OPERATORS and
                   ((token == '^' and operators[-1] != '^') or
                    (operators[-1] in ('^', 'u') and PRECEDENCE[operators[-1]] >= PRECEDENCE[token]) or
                    (operators[-1] not in ('^', 'u') and PRECEDENCE[operators[-1]] > PRECEDENCE[token]))):
                output.append(operators.pop())
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            if not operators:
                raise ValueError("Mismatched parentheses")
            operators.pop()  # Remove '('
            if operators and operators[-1] == 'u':
                output.append(operators.pop())
            if not operators or operators[-1] != '(':
                raise ValueError("Mismatched parentheses")
        else:
            raise ValueError(f"Invalid token: {token}")
    while operators:
        op = operators.pop()
        if op in ('(', ')'):
            raise ValueError("Mismatched parentheses")
        output.append(op)
    return output

def evaluate_rpn(rpn):
    stack = []
    for token in rpn:
        if isinstance(token, float):
            stack.append(token)
        else:
            if len(stack) < 2:
                raise ValueError("Insufficient operands")
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(a / b)
            elif token == '^':
                stack.append(a ** b)
            elif token == '%':
                if b == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(a % b)
            else:
                raise ValueError(f"Unknown operator: {token}")
    if len(stack) != 1:
        raise ValueError("Malformed expression")
    return stack[0]

def parse_unary_minus(tokens):
    output = []
    operators = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token == '-' and (i == 0 or tokens[i-1] in ('(', '+', '-', '*', '/', '^', '%')):
            # Unary minus
            operators.append('u')
        else:
            output.append(token)
        i += 1
    return shunting_yard(output + operators)

def calculate(expression):
    tokens = tokenize(expression)
    rpn = parse_unary_minus(tokens)
    result = evaluate_rpn(rpn)
    return str(result)

@app.route('/calculator', methods=['POST'])
def calculator():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({"error": "Invalid input"}), 400
    expression = data['expression']
    if not isinstance(expression, str):
        return jsonify({"error": "Invalid input"}), 400
    try:
        result = calculate(expression)
        return jsonify({"result": result}), 200
    except (ValueError, ZeroDivisionError):
        return jsonify({"error": "Invalid input"}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
